    futureDesc: 'يمثّل نموذج DeHub للمحتوى المجزأ بمعيار ERC-1155 تطوراً من علاقات مؤقتة بين المبدع والمعجب إلى شراكات اقتصادية دائمة. فبإتاحة سكّ أي رفع إلى 1000 جزء قابل للتداول للمبدعين، نبني أول منصة يعود فيها نجاح المحتوى بالفائدة مباشرة ودائماً على كل المعنيين — المبدعين والمعجبين والمستثمرين — إلى الأبد، دون جهد مستمر أو اعتماد على المنصة.',
