    liveStreamDesc: 'انتقل إلى البث المباشر من مؤلف المنشور أو في متصفحك أو من برنامج ترميز. يتم نشر التدفقات إلى DeHub الخاصة وتشغيلها عبر WebRTC في الوقت الفعلي تقريبًا، مع Livepeer كاحتياطي تلقائي عندما لا تتمكن الشبكة من الوصول إلى الإدخال. كل بث غير مصرح به ومقاوم للرقابة، وله دردشة خاصة به، ويتحول إلى إعادة في اللحظة التي ينتهي فيها.',
