    multipostDesc: 'انشر على DeHub وعلى حساباتك الاجتماعية الأخرى في نفس الخطوة. قم بتوصيل الحسابات مرة واحدة في الإعدادات → المنشورات المتعددة، ثم اختر المكان الذي تذهب إليه كل منشور من أيقونة المنشورات المتقاطعة في المؤلف. يبقى DeHub موطن المنشور ؛ تحمله النسخ إلى الجماهير التي لديك بالفعل في مكان آخر.',
