    spSafetyDesc: 'يتم إعادة فحص كل سحب مقابل المنشور كما هو في تلك اللحظة، لذا فإن المنشور الذي تم حذفه أو حظره أو وضع علامة عليه كمحتوى ناضج لا يصل أبداً إلى خلاصة الغريب. يتم رفض المنشورات الناضجة عند الحجز أيضاً، ولا يتم التعامل مع التعزيز لشخص قام بحظرك أو الشخص الذي قمت بتعزيزه.',
