    uploadAudio: 'الموسيقى والمنشور الصوتي المنطوق مثل أي تنسيق آخر، مع مرئي على البطاقة ولاعب ركني يستمر في اللعب أثناء استمرارك في التمرير على الخلاصة.',
    workB1: 'انشر مكافأة:',
    workB2: 'كن صياداً:',
    workB2Desc: 'تصفح المكافآت المفتوحة، وصفّها حسب الفئة أو العملة، وطالب بما تريد، وأرسل عملك لتحصيل المكافأة. كل مستخدم يمكن أن يكون صياداً، دون تقديم طلب ودون حراسة بوابات.',
