    accountsB4Desc: 'خلك تحتفظ بأكثر من حساب جنبًا إلى جنب في الإعدادات → الملف الشخصي وبدل بينهم بدون ما تسجل خروج وتسجيل دخول. مستوى شارتك يحدد كم حساب تقدر تحتفظ فيه.',
    accountsB7Desc: 'نموذج تسجيل الدخول فيه خيارات منفصلة لاستيراد مفاتيح محفظة عندك بالفعل ولترحيل حساب DeHub سابق، عشان التسجيلات الجديدة ما تضطر تختار بينهما.',
    accountsB8Desc: 'تقدر تحذف حسابك بنفسك من الإعدادات. ملفك، التحميلات والوسائط المخزنة، بما فيها النسخ الاحتياطية، تُمسح، ورابط تسجيل الدخول بـApple يُسحب. أي شيء مكتوب بالفعل على بلوكتشين عام يظل هناك.',
