    affiliateB3Desc: 'لوحة تحكم الشركاء تعرض نقراتك، التسجيلات وأرباحك، وتخليك تخصص صفحة الدعوة وصورة المشاركة. زياراتك الخاصة ما تُحسب.',
    aiSuiteB3Desc: 'وصف تطبيق بلغة بسيطة لـ@assistant في رسائلك وهو يبنيه، بعدين يعطيك رابط معاينة مباشر قابل للمشاركة. dehub.io/builder يبدأ المحادثة لك.',
    aiSuiteCreditsDesc: 'التوليد يُدفع بعملات DeHub. السيرفر يحدد سعر الشغل قبل ما يشتغل، أنت توافق على تحويل واحد، والشغل يبدأ بعد ما يتأكد الدفع على السلسلة. كل محفظة تحصل على خمس صور مجانية على أقل النماذج تكلفة لتجربتها، ورصيد من العملات ذات القيمة بالدولار على صفحة المبدع يقدر يدفع للشغل بدون توقيع محفظة كل مرة. الدبلجة المرحلية تُحسب بنفس الطريقة، بالدقيقة.',
