    topUpDesc: 'لدينا عملة داخل التطبيق الخاصة بنا،  مشابهة ل Vbucks التي توجد في Fortnite أو TikTok coins،  ours هي DeHub tokens.  ستظهر هذه العملات كعملات ذهبية عبر التطبيق.  تستخدم هذه العملات لخدمات الأقران مثل المشاركات والاشتراكات وغيرها.  يعتبر التصفح مجاناً،  وكذلك نشر المحتوى داخل الحد الأسبوعي الذي يتلقاه كل حساب - إذا قمت بتسجيل الدخول مع حساباتك الاجتماعية أو البريد الإلكتروني أو الرسائل القصيرة،  فنحن نsponsor جميع رسوم الغاز لك.  يستخدم مستخدمي الحافظة رسوم الغاز القياسية لETH أو BNB.  زيادة المال في 2 نقرات أدناه.',
