    topUpCardDesc: 'تتوقف صفحة الشراء على DeHub Pay.  يمكنك الدفع بالبطاقة،  أو الدفع بالكريبتو الذي تحمله على شبكة أخرى ويتحول لك.  يبدأ الحد الأدنى من $0.50.  يمكن شراء ETH وUSDC بالبطاقة من خلال MoonPay،  على الشبكة التي تتواجد عليها،  وينتهي به المطاف في الحافظة التي قمت بتسجيل الدخول إليها.  بمجرد وصول الشراء،  يمكنك مشاركته في التغريدات بضغطة زر واحدة.',
