    tokenDisclaimer: 'يتم استخدام تطبيقات DeHub كعملة ذات استخدامات داخل نظامنا، مثل العملات المستخدمة في الألعاب، وليس كأدوات استثمارية. بينما توفر بنية تحتيةنا blockchain شفافية غير مسبوقة وبيانات متصلة على الشبكة للاستخدام التعليمي، فإن جميع الأسواق تحمل مخاطرًا معينة. يمكن أن تفقدوا استثماراتكم بالكامل بسببInstability السوق، أو مشاكل تقنية، أو اختراقات أمنية، أو ظروف غير متوقعة. لا تتشارك إلا بالأموال التي يمكنكم فقدانها بالكامل. يتحمل DeHub وشركاؤه مسؤولية أي خسائر مالية محتملة.',
