    badgeDesc: 'كلما كان لديكم أكثر من DeHub tokens، كان ذلك أكثر إثارة. هذا يشمل ولكن ليس محصورًا في نظام شارة الشرف الذي يفتح ميزات جميلة على ملفات تعريفك العامة بالإضافة إلى ميزات متقدمة أخرى.',
    badgePriceTitle: 'الدرجات المحددة بالدولار',
    badgePriceDesc: 'يتم تحديد درجاتنا في 13 درجات، من Crab إلى Megalodon، كل درجاتها تتحمل تكلفة ثابتة بالدولار وليس عدد ثابت من التطبيقات. يطلب من كل درجة عدد DeHub tokens يحتاجه ذلك التكلفة في السوق الحية، لذلك فإن شارة الشرف تعني نفس الالتزام بغض النظر عن ما يحدث في السوق. يأتي معها حمايةان: لا يرتفع الالتزام أبدًا عن الأرقام المنشورة إذا انخفض السعر، ومرة واحدة لديكم درجة، فلا يمكن فقدانها - يتم حجز شارة الشرف التي حصلت عليها في الدرجة الأرخص التي حصلت بها عليها، لذلك لا يمكن أن يأخذها منكم انخفاض السعر.',
    badgeUnlockTitle: 'ماذا يفتح شارة الشرف',
    badgeUnlock2: 'حسناً يوميًا من المشاركات المجانية، وخصمًا على أي شيء بعد ذلك.',
    badgeDelegationTitle: 'أعرض شارة شرفك',
    badgeDelegationDesc: 'يمكنك إعارة شارة شرفك. كل درجة تمنحك مكانًا واحدًا في إعارة - واحدًا في Crab، و13 في Megalodon - وكل مكان يمنح حسابًا آخر درجتك لمدة ما يبقى فيها هناك. يوجد لأن التأثير على DeHub يُعتزم أن ينتقل مع مجموعة وليس يبقى على حساب واحد: يمكن للفرق والفرق وال حسابات الثانوية الحصول على درجتهم من من يؤمن لهم، دون أن ينتقل أي منهم من التطبيقات أو يمنحوا المفتاح.',
    badgeDelegationB1: 'درجة واحدة، وليس واحدة أقل:',
