    badgeDelegationB4Desc: 'خذ مكانًا من المكان وسترجع درجتك. استثماركم الخاص ومستوى الرسوم والشارة المحجوزة لا تتأثر بأي شيء تمنحونه.',
    badgeDelegationB5: 'الوضع، وليس الحقوق:',
