    badgeDelegationB7Desc: 'يظهر شارة الشرف المقدمة ل حساب في جرس التنبيه الخاص به، ويمكنه رفضها. يمكنكما إنهاء الإعارة بعد ذلك.',
    tipTitle: 'أعرض على من تحب',
    tipDesc1: 'خدمات التوجيه المدمجة عبر جميع المشاركات والبث المباشر فقط تأتي مع رسوم 10%، مقارنة بالرسوم العادية 60% التي تفرضها مثل TikTok وصناع الأعمال الآخرون، بالإضافة إلى القدرة على التصويت على إلغاء الفيديوهات مما يعطي السلطة مرة أخرى في أيدي المشاهدين.',
