    superPowersDesc: 'تحويل شارة الاستثمار إلى إمكانية الوصول التي يمكنك إنفاقها. كل أسبوعين، تمنحك الشارة زيادات، وإنفاق واحدة يضع المنشور في المكان الأول في feed المنزلية. Team up مفتوح للجميع ويتحدى قوة المحفظة من hasta ثمانية حسابات، مما يعطي كل عضو شارة مجموعها. المكان يتدور: عندما يكون هناك عدة زيادات، يتم توزيع المنشورات بشكل منحني حسب درجات الشارة، لذلك يتم عرض الدرجة الأعلى أكثر من مرة وكل شخص لا يزال يحصل على النافذة التي تم منحها.',
    superPowersDescV2: 'تحويل شارة الاستثمار إلى إمكانية الوصول التي يمكنك إنفاقها. كل أسبوعين، تمنحك الشارة زيادات، وإنفاق واحدة يضع المنشور في المكان الأول في feed المنزلية. Team up مفتوح للجميع ويتحدى قوة المحفظة من hasta ثمانية حسابات، مما يعطي كل عضو شارة مجموعها. المكان يتدور: عندما يكون هناك عدة زيادات، يتم توزيع المنشورات بشكل منحني حسب درجات الشارة، لذلك يتم عرض الدرجة الأعلى أكثر من مرة وكل شخص لا يزال يحصل على النافذة التي تم منحها.',
    boostPower: '1) زيادة',
    boostPowerDesc: 'ضع المنشور الأخير من الأسبوع في المكان الأول في feed المنزلية. يفتح عند قوس الحبار. الآن على قيد الحياة.',
    trendJackerDesc2: 'ضع واحدة من فئاتك في المكان الأول في قائمة التrending. يفتح عند الحوت الجياني. الآن على قيد الحياة.',
    timelineBomber: '5) Bomber التوقيت',
    timelineBomberDesc2: 'يرى متابعوك المنشور قبل أي منشور آخر - ملك الحيات يفوق الحوت الأعظم للناس الذين اختروا سماعهم. يفتح عند ملك الحيات. الآن على قيد الحياة.',
    superPowersMore2: 'جميع السلطة العشرة هي على قيد الحياة والموجودة في التطبيق. Anchor التعليق يحتفظ بتعليقك في المكان الأول في حوار شخص آخر. Flare الإشارة يرسل تنبيهًا واحدًا إلى كل حساب يتابعك. Flak Jacket يجعل المنشور مقاومًا للقبر الإلغاء أثناء تشغيله. Team up يسمح بجمع قوة المحفظة من حتى ثمانية حسابات، مما يعطي كل عضو شارة مجموعها. Front Row يضع المسرح الذي تستضيفه في المكان الأول في سلك المسرح. Deep Current يعطي أحد زياداتك لمنشور شخص آخر.',
    superPowersMoreV2: 'جميع السلطة العشرة هي على قيد الحياة والموجودة في التطبيق. Anchor التعليق يحتفظ بتعليقك في المكان الأول في حوار شخص آخر. Flare الإشارة يرسل تنبيهًا واحدًا إلى كل حساب يتابعك. Flak Jacket يجعل المنشور مقاومًا للقبر الإلغاء أثناء تشغيله. Team up يسمح بجمع قوة المحفظة من حتى ثمانية حسابات، مما يعطي كل عضو شارة مجموعها. Front Row يضع المسرح الذي تستضيفه في المكان الأول في سلك المسرح. Deep Current يعطي أحد زياداتك لمنشور شخص آخر.',
