    spRotationTitle: 'كيف يتم توزيع المكان',
    spRotationDesc: 'يتم تدوير المكان بدلاً من ربطه. عندما يكون هناك زيادات متعددة في نفس الوقت، يُمنح كل مشاهد واحدًا، مقاسمةً على درجات البوستر - درج أعلى يظهر أكثر، وكل شخص يرى الزيادة التي دفع لها. ما يشتروي الزيادة هو جزء من الكلام لمدة عدد معين من الدقائق، وليس امتلاكك للجزء العلوي من feed بشكل حصري.',
    spCycleTitle: 'ساعة واحدة للجميع',
    spSafetyTitle: 'ما لا يمكن للزيادة أن تفعله',
    feedsMedia: 'فيديوهات وصور في الشبكة',
    feedsMediaDesc: 'تظاهر الفيديوهات والصور بتصميمها الأصلي بدلاً من أن تكون محاطة بالأسود. على الهواتف، يأخذون نصف الشاشة تقريبًا ويلعبون كإشعارات مكتومة مع زر غير صوتي فقط؛ انقر على واحد وسيفتح في متصفح Shorts وسيستمر في تشغيل آخر فيديوهات Shorts. على الأجهزة الكبيرة، يأخذون ثلاثة أرباع الشاشة، مع ظهور الإعدادات عند النقر فوقها. يتبع-carousel Shorts المنشور الأول في الصفحة الرئيسية ويعود في الأسفل، ولا يظهر نفس المبدعين مرتين متتاليتين.',
    feedsSoundtrack: 'صور الصوت',
    feedsSoundtrackDesc: 'يمكن أن يحمل المنشور الصور الصوتية. يظهر ككبسولة زجاجية صغيرة تفتح في موجة في أسفل الصورة، ويعرض مباشرة من التغريدات، ويمكنك تحريكه لتحديد المكان. الصور الصوتية تفتح في فيديوهات قصيرة، والصور العادية تفتح المنشور.',
    feedsShare: 'النشر الغني',
    feedsShareDesc: 'مخطوطات روابط Polymarket و Manifold و votes في Snapshot و Audius و صفحات DeFi و غيرها تفتح في بطاقات غنية مصممة من قبل المصدر نفسه. مشاركة منشور من DeHub تظهر صورة منه، بما في ذلك المنشورات النصية، داخل إطار DeHub مع إنجازاته.',
    communitiesB2: 'المجتمع:',
    communitiesB4: 'توسيع وتعديل:',
    communitiesB4Desc: 'دعوة متابعيك إلى مجتمع واطلع على من قام بالدعوة، واضافة المنشورات التي قمت بpublicationها دون نسخ إجاباتهم، واطلع على الأعضاء الذين قاموا بالتطوع في الآخر.',
    stagesTitle: 'المراحل: غرف الصوت الحية',
    stagesDesc: 'المراحل هي غرف الصوت الحية، مشابهة ل Twitter Spaces، مصممة بشكل مباشر في DeHub. يفتح المضيف غرفة، ويحضر المتحدثين على المسرح، ويمكن للعدد الكبير من المستمعين الدخول في الحال من صفحة المراحل أو رابط الدعوة المشترك. تم تصميم المراحل لمناقشات حية على نطاق واسع: يتحكم المضيف في من يمكنه الكلام، ويمكن للمستمعين إرسال إجابات حية، ويمكن تسجيل الغرفة بأكملها للاستخدام مجدداً.',
    stagesDesc2: 'ما يفارق DeHub المراحل هو طبقة الإنتاج. يحصل المضيفون على لوحة DJ- style التي تجمع بين تأثيرات الصوت، وملفات الموسيقى الخاصة بهم، وملفات إذاعة حية في الصوت المنشور، بالإضافة إلى تأثيرات الصوت، بحيث يمكن للغرفة أن تشعر مثل عرض منتج أكثر من مؤتمر هاتفي. يمكن للمضيفين مشاركة الشاشة، والعمل بكل شيء من متصفح واحد بدون OBS أو مفاتيح البث، ويمكنهم جدولة الغرفة مقدماً بحيث يكون الجمهور مستعداً قبل فتح الأبواب.',
    stagesDesc3: 'الغرفة أيضاً قابلة للقراءة. يتم وضع الكلمات المكتوبة الحية على كل متحدث كما يتحدث، وترجمت إلى اللغة التي يقرأها كل مستمع، بحيث يمكن للمراحل أن يتابعها شخص ما لا يتحدث أي لغة على المسرح. يتم التحدث الحية عن الغرفة في صوت مضيفهم المنسخ، وتم حساب الساعة من قبل ديهوب التوكين. يوجد خزانة نصوص حية وترجمة النص إلى صوت لجعل الغرف قابلة للاستخدام بدون ميكروفون، ويمكن للمستخدمين متابعة باقي التطبيق بينما يلعب المرحلة.',
    stagesB1: 'المضيف و الكلام:',
    stagesB2: 'الإجابات و لوحة الصوت:',
