    stagesB5: 'التخطيط و الإشعار:',
    stagesB5Desc: 'الإعلان عن المرحلة مقدماً بوقت قصير مع رابط دعوة قصير، وكل من قام بإعداد إشعار سيتم تنبيهه عندما تكون قريباً من بدء المرحلة، ومرة أخرى في اللحظة التي يتم فيها البث الحية.',
    stagesB6Desc: 'الكلمات المكتوبة الحية لكل متحدث، مترجمة إلى اللغة التي يقرأها كل مستمع. يتم الاحتفاظ بالنصوص الدائمة بعد انتهاء الغرفة.',
