    tvRadioB3: 'الإذاعة:',
    tvRadioB3Desc: 'يتم بث إذاعات مدروسة من قبل الفئة، مع لاعب صوت دائم وخيارات عرض صوتي متوفرة.',
    walletHubTitle: 'المحفظة و المدفوعات',
    walletHubDesc: 'يأتي كل حساب DeHub مع محفظة مدمجة، غير المخزنة. لا يوجد إضافات متصفح للاستخدام، ولا عبارات البذرة للاستخدام: يتم إنشاء المحفظة و حماية الملف الشخصي عند تسجيل الدخول للمرة الأولى، وتمكّنها من كل عملية انتقال قيمة في التطبيق، من التبرع والفتح المطلوب مقابل المشاهدة إلى الاشتراكات والجوائز والربح من قبل المبدعين. يتم إرسال التوكين إلى مستخدم آخر بلا مقابل، وتمكّن الأدوات من إخفاء معظم المستخدمين عن العنوان المادي للمحفظة أو المفتاح الخاص.',
    walletHubB1: 'المحفظة:',
    walletHubB1Desc: 'محفظة متعددة الشبكات تحمل توكين DeHub جنباً إلى جنب مع ETH و BNB و USDT و USDC وغيرها من العملات في Base و BNB Chain و Ethereum و Robinhood Chain و Arc، بالإضافة إلى ملكية Solana الخاصة بك. يتم إخفاء الصفرات، وسيطلب التطبيق منك تحديد الشبكة قبل نسخ العنوان. يمكنك استلام و إرسال و شراء و تجارة و استثمار و توصيل و تحويل إلى المال من خلال زر واحد من الميزانية.',
    walletHubB2: 'مركز الأوامر:',
    walletHubB3Desc: 'تعبئة المال في التطبيق من خلال DeHub Pay، من خلال البطاقة أو من خلال العملة المالية من الشبكة الأخرى، من $0.50.',
