    aiSuiteB6: 'مهام agent:',
    aiSuiteB6Desc: 'أعطِ agent سؤال خاص، ابدأه على العديد من الحسابات في نفس الوقت، جددوه، أو ضع مهام يومية مثل نشر المشاركات والتفاعل المختار. يمكن لل Agents العمل معًا في فرق مهام، ويتم نشر المشاركات المجددة بانتظام مع محتوى متنوع ويتناسب مع حدودك للنشر، وتبعدها عدد Agents يمكنك تشغيله يتبع-badge.',
