    adsPortalTitle: 'بوابة الإعلانات',
    adsPortalLink: 'اقرأ المزيد من وثائق الإعلانات',
    featureBoardTitle: 'طلبات الميزات',
    featureBoardDesc: 'يتم بناء DeHub مع مجتمعه. قدم أفكارك على لوحة طلبات الميزات، التصويت على طلبات الآخرين، واطلع على تحديثاتهم - إذا تمت إضافة ميزة طلبتها، سيخبرك التطبيق بذلك من خلال إشعار شخصي. الآن يفتح طلبات الميزة كعملية عمل أولاً: وصف فكرة أو تحسين أو عطل، أضف شاشات المخاطرة، واضغط على زر واحدة.',
    featureBoardDesc2: 'يوجد صفحة خاصة للتعليقات التي تحتوي على كل ما نشره المجتمع، يمكن الوصول إليها من القائمة الرئيسية والقائمة الأدوات.',
    connectTitle: 'رابط Connect AI (MCP)',
    connectDesc: 'ربط DeHub بChatGPT أو Claude عن طريق MCP واستخدم AI المفضلة لديك لتصفح، نشر، وتفاعل مع المنصة على behalfك. قم بتركيبها على dehub.io/connect.',
    notificationsTitle: 'الإشعارات',
    notificationsDesc: 'كل ما يحدث لك يصل إلى مركز إشعارات واحد، يُقسم إلى أقسام لئلا تُغمرك الإجابات. التعليقات والإجابات، والتفاعل على مشاركاتك، والمتابعين الجدد، والرسوم، والشراء، والذكريات، واللحظة التي يبدأ فيها عرضك المحدد، والنشاط المجتمعي، والتنبيه عندما يتم إطلاق ميزة طلبتها على لوحة طلبات الميزات - كل ذلك في نفس المكان، مع صورة مصغرة لما يخص الإشعار حتى يمكنك تمييزها بسهولة.',
    notificationsB1Desc: 'تفضيلات الفئات في الإعدادات تحدد ما يصل إليك، لذلك يمكنك تجاهل الرسوم والتفاعلات. يُصنع كل قسم بناءً على النشاط، ويظهر كل قسم عدد غير قرئ، ويمكنك اختيار تنبيهات الدردشة العامة مع حد أقصي للرسائل التي يمكنها أن تصل إليك في الساعة.',
    notificationsB2: 'باستخدام push على الويب والجوال:',
    notificationsB3Desc: 'الاعلانات المنشورة على المنصة تصل عبر نفس المركز بدلاً من inbox منفصل للاستجابة.',
    notificationsB4: 'باستخدام البريد الإلكتروني:',
    notificationsB4Desc: 'ربط عنوان بريدك الإلكتروني وسيصل لك الفئات التي اخترتها أيضًا في صندوق البريد، وهو ما يلتقط الأشياء التي ترغب في عدم تجاهلها أثناء إغلاق التطبيق.',
    notificationsB5: 'باستخدام الرسائل النصية:',
    tocKids: 'حالة الأطفال',
