    importantNoticeText: 'DeHub بتعمل كبروتوكول ديسنترياليزي. ماعندناش إلا نعمل على حماية خصوصية المستخدمين، لكن بسبب الطبيعة الديسنترياليزية، ممكن أن تكون التفاعلات مرئية على سلاسل الكتل العامة. على المستخدمين فهم آثار الخصوصية لعملياتهم على السلاسل.',
