    useContentDesc: 'افتح قفل عمليات الرفع بالدفع لكل مشاهدة والمنشورات المقفلة بالرموز والرسائل المميزة واشتراكات المبدعين. ويُدفع للمبدع عند فك القفل لا بعد 30 يوماً.',
