    useFeesTitle: 'الرسوم والرهن والحوكمة',
    useRewardsDesc: 'دفعات x -2 - اكسب، ومكافآت المشاهدة، والمكافآت على المحتوى المنشور، والسحوبات، والألعاب والحملات المجتمعية كلها مقومة ومدفوعة برموز DeHub.',
    useRewardsTitle: 'عملة المكافآت',
    useTippingTitle: 'إكرام المبدعين',
    intro: 'دِهوب توكِينات (DeHub tokens) هيا العملة المفيدة الأصلية لشبكة دِهوب، وDHB هيا رموزها. هيا الوحده الوحيده اللي بتستخدم في كل دِهوب دَأب (d\'app) — اللي بتستخدمها في التِيب، فتح المحتوى، كسبها من مشاهدة و خلقة، و استهلاكها في توليد الذكاء الاصطناعي. عشان هيا على السِلك (on-chain)، كل حركة قيمة في الإيكوسِستم هيا مشفرة و مرئية للجميع، مافيشها في سجل خاص لازم نؤمنك بيها.',
    howItWorksDesc1: 'كل حساب في ديهاب بيكون فيه محفظة مدمجة. بتستطيع تملئها من خلال بطاقة عن طريق بوابة ستريب، أو تقبلها من مستخدم تاني، أو تكسبها من المنصة، أو تودعها من أي محفظة ذات إدارة ذاتية — ما تحتاجش تطبيق تاني، أو امتداد، أو جملات بذرة لتبدأ. البلقات، التوصيات، الفتحات، والأجور كلها بتتساوي في عملات ديهاب، فالمبلغ بيحرك بين المستخدمين مباشرة بدل ما يروح من خلال معالج دفع بياخد نسبة ويقدر يجمد الحساب.',
    useCasesTitle: 'لما هو بيستخدمش فيه؟',
    useTippingDesc: 'أرسِلِ القيمة مباشرةً للصانع في المنشور أو البث المباشر أو المسرح — فورًا، عالميًا، وبدون وسيط يسرق جزء من الإرسال.',
    useCommerceDesc: 'اشترِ المنتجات، الكولكتيبلات الرقمية، الخدمات، ونفطات NFT الفزيوية الرقمية من متاجر المبدعين والمسوق من خلال حساب واحد.',
    useFeesDesc: 'دفع رسوم الشبكة، استثمر في مستويات النادي للحصول على نصيب من أرباح البروتوكول، واحرق عملات DeHub لإصدار أصوات في قرارات البروتوكول.',
    profitShareDesc2: 'الوزعيات بتتغذى من ما بيحصل عليه البروتوكول من أرباح، على فترات متغيرة، وبتوزع على طبقات الاستيكينج حسب الكمية والوقت اللي بيستاك فيه. الاستيكينج لفترات أطول بيحصل على نصيب أكبر من كل توزيع. شوف استيكينج ليه تفاصيل الطبقات والحسابات الدقة للأجور.',
    pegTitle: 'الأسعار المحددة مسبقًا وطرحها على البورصة غير المركزية (DEX)',
    pegDesc1: 'الديهاب توكن هو توكن مفيد. حاليًا، هو معلق بسعر 0.001 دولار لكل توكن لأغراض داخل التطبيق، وهو نفس السعر الذي تراه عند الشراء من خلال بوابة العملات الورقية، والسعر المستخدم في تسعير داخل التطبيق. هذا المعلق موجود للحفاظ على اقتصاد التطبيق مستقر ومتوقع أثناء توسيع الشبكة — إنه معدل حسابي داخلي، وليس سقفًا، أو ضمانًا، أو وعدًا بقيمة مستقبلية.',
    disclaimerText: 'رموز DeHub مخصصة حصريًا للأغراض التشغيلية بنفس طريقة أي رموز أو عملات رقمية داخل الألعاب أو التطبيقات، وهي ليست استثمارًا على الإطلاق. بما أن رمزنا يعيش على السلسلة، يمكننا تقديم فائدة إضافية بالإضافة إلى مستويات غير مسبوقة من الشفافية القابلة للتحقق. البيانات أعلاه مجمعة فقط لأغراض الشفافية والتعليم والمعلومات فقط. لا تتحمل DeHub وجميع الشركات التابعة لها أي مسؤولية عن الخسائر المالية المتكبدة من شراء أي رموز أو NFTs نطلقها. الأسواق شديدة التقلب. يمكنك أيضًا أن تخسر كل أموالك بسبب أي أخطاء غير متوقعة مثل فشل الكفاءة، أو خطأ تقني، أو اختراقات، وما إلى ذلك. لذلك، يجب عليك دائمًا إنفاق ما يمكنك تحمل خسارته فقط.',
